// Generated from Natural Earth 1:110m admin-0 countries (public domain).
// Miller cylindrical projection, Antarctica removed. Keyed by ISO 3166-1 alpha-2;
// regions without an ISO code use a leading underscore and can never be claimed.
// PAD_TOP adds an ocean band above the Arctic so the land mass sits centred in the frame.

export const MAP_WIDTH = 1000
export const MAP_HEIGHT = 546.8
export const LAT_TOP = 83.7
export const LAT_BOTTOM = -56
const PAD_TOP = 56

const miller = (lat: number) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * (lat * Math.PI) / 180))

// Project lon/lat (degrees) into map coordinates, for overlays like the graticule.
export function projectX(lon: number) {
  return ((lon + 180) / 360) * MAP_WIDTH
}

export function projectY(lat: number) {
  return (miller(LAT_TOP) - miller(lat)) * (MAP_WIDTH / (2 * Math.PI)) + PAD_TOP
}

export interface CountryShape {
  name: string
  // Centroid of the largest landmass, in map coordinates. Used to aim troop arcs.
  anchor: [number, number]
  d: string
}

